// Program 11.1: Even or odd
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter a number: ";
    cin >> n;
    if (n % 2 == 0)
        cout << n << " is even." << endl;
    else
        cout << n << " is odd." << endl;
    return 0;
}

// Program 11.2: Is the citizen eligible to vote?
