// Program 11.3: Largest of three numbers
#include <iostream>
using namespace std;

int main() {
    int a, b, c;
    cout << "Enter three numbers: ";
    cin >> a >> b >> c;
    if (a >= b && a >= c)
        cout << "Largest = " << a << endl;
    else if (b >= a && b >= c)
        cout << "Largest = " << b << endl;
    else
        cout << "Largest = " << c << endl;
    return 0;
}

// Program 11.4: Grade from percentage (else-if ladder)
#include <iostream>
using namespace std;

int main() {
    double per;
    cout << "Enter percentage: ";
    cin >> per;

    if (per < 0 || per > 100)
        cout << "Invalid percentage!" << endl;
    else if (per >= 90)
        cout << "Grade A1 - Outstanding" << endl;
    else if (per >= 75)
        cout << "Grade A2 - Excellent" << endl;
    else if (per >= 60)
        cout << "Grade B - Very Good (First Division)" << endl;
    else if (per >= 45)
        cout << "Grade C - Good (Second Division)" << endl;
    else if (per >= 33)
        cout << "Grade D - Pass (Third Division)" << endl;
    else
        cout << "Grade E - Needs improvement (Fail)" << endl;
    return 0;
}

// Program 11.5: Electricity bill with slab rates
// (Rates are only for practice, not real tariff values.)
// First 100 units: Rs 4 per unit
// Next 100 units (101-200): Rs 5 per unit
// Above 200 units: Rs 6.5 per unit
// Fixed charge: Rs 50
#include <iostream>
using namespace std;

int main() {
    int units;
    cout << "Units consumed: ";
    cin >> units;

    double energy;
    if (units <= 100)
        energy = units * 4.0;
    else if (units <= 200)
        energy = 100 * 4.0 + (units - 100) * 5.0;
    else
        energy = 100 * 4.0 + 100 * 5.0 + (units - 200) * 6.5;

    double total = energy + 50;
    cout << "Energy charge = Rs " << energy << endl;
    cout << "Fixed charge  = Rs 50" << endl;
    cout << "Total bill    = Rs " << total << endl;
    return 0;
}

// Program 11.6: Leap year check (nested if)
#include <iostream>
using namespace std;

int main() {
    int year;
    cout << "Enter a year: ";
    cin >> year;

    if (year % 4 == 0) {
        if (year % 100 == 0) {
            if (year % 400 == 0)
                cout << year << " is a leap year." << endl;
            else
                cout << year << " is not a leap year." << endl;
        } else {
            cout << year << " is a leap year." << endl;
        }
    } else {
        cout << year << " is not a leap year." << endl;
    }
    return 0;
}

