// Program 11.9: Ticket price using the conditional (ternary) operator
#include <iostream>
using namespace std;

int main() {
    int age;
    cout << "Visitor's age: ";
    cin >> age;
    int price = (age < 12 || age >= 60) ? 20 : 50;
    cout << "Museum ticket: Rs " << price << endl;
    return 0;
}
